# Removes redundant Start Selling nav link and adds a real Log In option
# on both desktop and mobile for logged-out visitors.
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\components\NavClient.tsx"), $bytes)
Write-Host "UPDATED: src\components\NavClient.tsx" -ForegroundColor Green
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan